<template>
    <div>
        <Head title="Extended Forms" />

        <div class="row">
            <div v-for="picker in datePickers" :key="picker.id" class="md:col-4">
                <Card :title="picker.label" :icon="picker.icon" card-header-class="card-header-rose">
                    <div class="extended-date-picker">
                        <VueDatePicker
                            v-model="picker.value"
                            :time-picker="picker.id === 'time'"
                            :time-config="{ enableTimePicker: picker.id === 'datetime' || picker.id === 'time' }"
                            :formats="{ input: picker.format }"
                            :model-type="picker.modelType"
                            :auto-apply="picker.autoApply"
                            :aria-labels="{ input: picker.label }"
                        />
                    </div>
                    <p class="mt-2">Selected value: {{ picker.value }}</p>
                    <code v-if="picker.modelType">model-type="{{ picker.modelType }}"</code>
                    <code v-if="picker.autoApply">auto-apply</code>
                </Card>
            </div>
        </div>

        <Card>
            <div class="row gy-4">
                <section class="md:col-6">
                    <h4 class="title">Switches</h4>
                    <Toggle v-model="switchOn" label="Toggle is on" />
                    <Toggle v-model="switchOff" label="Toggle is off" />
                </section>
                <section class="md:col-6">
                    <h4 class="title">Customisable Select</h4>
                    <div class="row gy-3">
                        <div class="md:col-6">
                            <Select42
                                v-model="singleOption"
                                class="w-100"
                                :options="singleOptions"
                                placeholder="Single Option"
                                aria-label="Single option"
                                :show-search="false"
                            />
                        </div>
                        <div class="md:col-6">
                            <Select42
                                v-model="cityOption"
                                class="w-100"
                                :options="availableCities"
                                placeholder="Add a city"
                                aria-label="Choose a city to add"
                                :allow-clear="false"
                                @update:model-value="addCity"
                            />
                            <ul v-if="selectedCities.length" class="list-unstyled d-flex flex-wrap gap-1 mt-2 mb-0">
                                <li v-for="city in selectedCities" :key="city">
                                    <button type="button" class="btn btn-sm btn-outline btn-round m-0" :aria-label="`Remove ${city}`" @click="removeCity(city)">
                                        {{ city }} <span aria-hidden="true">×</span>
                                    </button>
                                </li>
                            </ul>
                        </div>
                        <div class="col-12">
                            <span id="remote-cities-label" class="d-block mb-1">Remote city search</span>
                            <Select42
                                v-model="remoteCity"
                                class="w-100"
                                :ajax-url="remoteCitiesUrl"
                                placeholder="Search cities"
                                aria-labelledby="remote-cities-label"
                            />
                            <small>Try searching for Riga or London.</small>
                        </div>
                    </div>
                </section>
                <section class="md:col-6">
                    <h4 class="title">Tags</h4>
                    <TagInput v-model="tags" />
                </section>
                <section class="md:col-6">
                    <h4 class="title">Dropdown &amp; Dropup</h4>
                    <div class="row gy-2">
                        <div class="md:col-6">
                            <Dropdown label="Multilevel Dropdown" align="start" trigger-class="btn btn-primary btn-round w-100">
                                <template #trigger>Multilevel Dropdown</template>
                                <button v-for="action in menuActions.slice(0, 2)" :key="action" type="button" class="menu-item" @click="selectedAction = action">
                                    {{ action }}
                                </button>
                                <div class="submenu">
                                    <button type="button" class="menu-item" aria-expanded="false">Submenu</button>
                                    <div class="menu">
                                        <button type="button" class="menu-item" @click="selectedAction = 'Submenu action'">Submenu action</button>
                                        <div v-for="title in nestedMenus" :key="title" class="submenu">
                                            <button type="button" class="menu-item" aria-expanded="false">{{ title }}</button>
                                            <div class="menu">
                                                <button v-for="number in 2" :key="number" type="button" class="menu-item" @click="selectedAction = `${title} action ${number}`">
                                                    {{ title }} action {{ number }}
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </Dropdown>
                        </div>
                        <div v-for="menu in menus" :key="menu.label" class="md:col-6 mx-auto">
                            <Dropdown :label="menu.label" :placement="menu.placement" trigger-class="btn btn-primary btn-round w-100">
                                <template #trigger>{{ menu.label }}</template>
                                <h6 class="menu-header">Dropdown header</h6>
                                <button v-for="action in menuActions" :key="action" type="button" class="menu-item" @click="selectedAction = action">
                                    {{ action }}
                                </button>
                            </Dropdown>
                        </div>
                    </div>
                    <p v-if="selectedAction" class="mt-2 mb-0" role="status">Selected: {{ selectedAction }}</p>
                </section>
                <section class="md:col-6">
                    <h4 class="title">Progress Bars</h4>
                    <div
                        v-for="progress in singleProgress"
                        :key="progress.color"
                        class="progress"
                        :class="`progress-line-${progress.color}`"
                        role="progressbar"
                        :aria-label="progress.label"
                        :aria-valuenow="progress.value"
                        aria-valuemin="0"
                        aria-valuemax="100"
                    >
                        <div class="progress-bar" :class="`progress-bar-${progress.color}`" :style="{ width: `${progress.value}%` }"></div>
                    </div>
                    <div class="progress-stacked progress-line-danger" role="group" aria-label="Stacked progress">
                        <div
                            v-for="progress in stackedProgress"
                            :key="progress.color"
                            class="progress"
                            :style="{ width: `${progress.value}%` }"
                            role="progressbar"
                            :aria-label="progress.label"
                            :aria-valuenow="progress.value"
                            aria-valuemin="0"
                            aria-valuemax="100"
                        >
                            <div class="progress-bar" :class="`progress-bar-${progress.color}`"></div>
                        </div>
                    </div>
                </section>
                <section class="md:col-6">
                    <h4 class="title">Sliders</h4>
                    <div class="pt-2">
                        <div ref="singleSlider" class="slider" @keydown="handleSliderKey"></div>
                        <div ref="rangeSlider" class="slider slider-info mt-5" @keydown="handleSliderKey"></div>
                    </div>
                </section>
                <section class="sm:col-4">
                    <h4 class="title">Regular Image</h4>
                    <ImagePicker v-model="image" :placeholder="imagePlaceholder" />
                </section>
                <section class="sm:col-4 md:col-3">
                    <h4 class="title">Avatar</h4>
                    <ImagePicker v-model="avatar" :placeholder="avatarPlaceholder" label="Add Photo" avatar />
                </section>
                <section class="sm:col-4 md:col-5">
                    <h4 class="title">Dropzone</h4>
                    <Toggle v-model="fullscreenDropzone" label="Fullscreen dropzone" />
                    <div class="dropzone-demo position-relative d-flex align-items-center justify-content-center mt-3 p-3 text-center">
                        <p class="mb-0">{{ fullscreenDropzone ? 'Drop files anywhere on this page.' : 'Drop files here.' }}</p>
                        <Dropzone :fullscreen="fullscreenDropzone" @files-dropped="droppedFiles = $event" />
                    </div>
                    <ul v-if="droppedFiles.length" class="list-unstyled mt-2 mb-0 text-break" aria-label="Dropped files">
                        <li v-for="(file, index) in droppedFiles" :key="index">{{ file.name }}</li>
                    </ul>
                </section>
            </div>
        </Card>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Select42 from '@sulzanoks/select42';
import { VueDatePicker } from '@vuepic/vue-datepicker';
import '@vuepic/vue-datepicker/dist/main.css';
import Card from '@scaffold/components/Card.vue';
import Dropdown from '@scaffold/components/Dropdown.vue';
import Dropzone from '@scaffold/components/Dropzone.vue';
import ImagePicker from '@scaffold/components/ImagePicker.vue';
import TagInput from '@scaffold/components/TagInput.vue';
import Toggle from '@scaffold/components/Toggle.vue';
import { extendedCities } from '@app/routes/demo/forms';
import avatarPlaceholder from '@scaffold-assets/avatar-placeholder.jpg';
import imagePlaceholder from '@scaffold-assets/image-placeholder.jpg';

export default {
    name: 'ExtendedFormsDemo',
    components: { Card, Dropdown, Dropzone, Head, ImagePicker, Select42, TagInput, Toggle, VueDatePicker },
    layout: { pageTitle: 'Extended Forms' },
    data() {
        return {
            datePickers: [
                { id: 'datetime', label: 'Datetimepicker', icon: 'today', format: 'yyyy-MM-dd HH:mm', value: new Date(2018, 10, 6) },
                { id: 'date', label: 'Date Picker', icon: 'library_books', format: 'yyyy-MM-dd', value: new Date(2018, 9, 6) },
                { id: 'time', label: 'Time Picker', icon: 'av_timer', format: 'HH:mm', value: { hours: 10, minutes: 5 } },
                { id: 'formatted', label: 'Formatted String Output', icon: 'event_note', format: 'dd.MM.yyyy', modelType: 'yyyy-MM-dd', value: '2018-10-06' },
                { id: 'auto-apply', label: 'Auto-Apply Date Picker', icon: 'event_available', format: 'yyyy-MM-dd', autoApply: true, value: null },
            ],
            switchOn: true,
            switchOff: false,
            singleOption: null,
            singleOptions: ['Foobar', 'Is great', 'Is bum', 'Is wow', 'boom'].map((text) => ({ value: text, text })),
            cities: ['Paris', 'Bucharest', 'Rome', 'New York', 'Miami', 'Piatra Neamt'],
            cityOption: null,
            remoteCity: null,
            remoteCitiesUrl: extendedCities.url(),
            selectedCities: [],
            menus: [
                { label: 'Dropdown', placement: 'bottom-start' },
                { label: 'Dropup', placement: 'top-start' },
            ],
            menuActions: ['Action', 'Another action', 'Something else here'],
            nestedMenus: ['Subsubmenu', 'Second subsubmenu'],
            selectedAction: '',
            tags: ['Amsterdam', 'Washington', 'Sydney', 'Beijing'],
            singleProgress: [
                { label: 'Primary progress', color: 'primary', value: 30 },
                { label: 'Info progress', color: 'info', value: 60 },
            ],
            stackedProgress: [
                { label: 'Success segment', color: 'success', value: 35 },
                { label: 'Warning segment', color: 'warning', value: 20 },
                { label: 'Danger segment', color: 'danger', value: 10 },
            ],
            image: null,
            avatar: null,
            fullscreenDropzone: false,
            droppedFiles: [],
            avatarPlaceholder,
            imagePlaceholder,
        };
    },
    computed: {
        availableCities() {
            return this.cities
                .filter((city) => !this.selectedCities.includes(city))
                .map((text) => ({ value: text, text }));
        },
    },
    async mounted() {
        const { default: noUiSlider } = await import('@scaffold/vendor/nouislider-10.0.0.js');
        const { singleSlider, rangeSlider } = this.$refs;
        if (!singleSlider || !rangeSlider) {
            return;
        }

        const range = { min: 0, max: 100 };
        noUiSlider.create(singleSlider, { start: 40, connect: [true, false], range });
        noUiSlider.create(rangeSlider, { start: [20, 60], connect: true, range });
        singleSlider.querySelector('.noUi-handle').setAttribute('aria-label', 'Slider value');
        const [minimum, maximum] = rangeSlider.querySelectorAll('.noUi-handle');
        minimum.setAttribute('aria-label', 'Minimum');
        maximum.setAttribute('aria-label', 'Maximum');
    },
    beforeUnmount() {
        this.$refs.singleSlider?.noUiSlider?.destroy();
        this.$refs.rangeSlider?.noUiSlider?.destroy();
    },
    methods: {
        handleSliderKey(event) {
            const handle = event.target.closest('.noUi-handle');
            const slider = event.currentTarget.noUiSlider;
            if (!handle || !slider || event.altKey || event.ctrlKey || event.metaKey) {
                return;
            }

            const handles = [...event.currentTarget.querySelectorAll('.noUi-handle')];
            const index = handles.indexOf(handle);
            const values = [slider.get()].flat().map(Number);
            const current = values[index];
            const destinations = {
                ArrowLeft: current - 1,
                ArrowDown: current - 1,
                ArrowRight: current + 1,
                ArrowUp: current + 1,
                PageDown: current - 10,
                PageUp: current + 10,
                Home: 0,
                End: 100,
            };
            if (!Object.hasOwn(destinations, event.key)) {
                return;
            }

            event.preventDefault();
            slider.set(values.map((_, handleIndex) => handleIndex === index ? destinations[event.key] : null));
        },
        async addCity(city) {
            await this.$nextTick();
            if (city && !this.selectedCities.includes(city)) {
                this.selectedCities.push(city);
            }
            this.cityOption = null;
        },
        removeCity(city) {
            this.selectedCities = this.selectedCities.filter((selected) => selected !== city);
        },
    },
};
</script>

<style scoped>
.dropzone-demo {
    min-block-size: 8rem;
    border: 1px dashed var(--border-color);
    border-radius: var(--radius-3);
}

.extended-date-picker :deep(.dp--theme-light) {
    --dp-background-color: var(--bg-2);
    --dp-text-color: var(--fg-body);
    --dp-hover-color: var(--bg-3);
    --dp-hover-text-color: var(--fg-body);
    --dp-border-color: var(--border-color);
    --dp-menu-border-color: var(--border-color);
    --dp-primary-color: var(--primary-bg);
    --dp-primary-text-color: var(--primary-contrast);
}
</style>
