<template>
    <div
        v-show="dragDepth > 0 || uploading"
        ref="overlay"
        class="dropzone-overlay"
        :class="{ 'dropzone-overlay--contained': !fullscreen }"
    >
        <div class="dropzone-content">
            <div role="status">{{ message }}</div>
            <progress
                v-if="uploading"
                :value="progress"
                max="100"
                aria-label="Augšupielādes gaita"
            ></progress>
        </div>
    </div>
</template>

<script>
import axios from 'axios';

export default {
    props: {
        uploadUrl: { type: String, default: '' },
        maxFileSize: { type: Number, default: 2000000 },
        allowedFileTypes: { type: Array, default: () => ['application/pdf'] },
        attachableType: { type: String },
        attachableId: { type: Number },
        uploadToStatus5: { type: Boolean, default: false },
        fullscreen: { type: Boolean, default: true },
    },
    emits: ['files-dropped', 'uploadSuccess'],
    data() {
        return {
            dragDepth: 0,
            uploading: false,
            progress: null,
            dragTarget: null,
        };
    },
    computed: {
        message() {
            if (!this.uploading) {
                return this.fullscreen ? 'Nomet jebkur!' : 'Nomet datnes šeit!';
            }

            return this.progress === null ? 'Augšupielādē…' : `${this.progress}%`;
        },
    },
    watch: {
        fullscreen() {
            this.bindDragEvents();
        },
    },
    mounted() {
        this.bindDragEvents();
    },
    beforeUnmount() {
        this.unbindDragEvents();
    },
    methods: {
        bindDragEvents() {
            this.unbindDragEvents();
            this.dragDepth = 0;
            this.dragTarget = this.fullscreen ? window : this.$refs.overlay.parentElement;
            this.updateDragListeners('addEventListener');
        },
        unbindDragEvents() {
            this.updateDragListeners('removeEventListener');
            this.dragTarget = null;
        },
        updateDragListeners(method) {
            this.dragTarget?.[method]('dragenter', this.handleDragEnter);
            this.dragTarget?.[method]('dragleave', this.handleDragLeave);
            this.dragTarget?.[method]('dragover', this.handleDragOver);
            this.dragTarget?.[method]('drop', this.handleDrop);
        },
        isFileDrag(event) {
            return event.dataTransfer?.types.includes('Files');
        },
        handleDragEnter(event) {
            if (this.isFileDrag(event)) {
                event.preventDefault();
                this.dragDepth++;
            }
        },
        handleDragLeave(event) {
            if (this.isFileDrag(event)) {
                this.dragDepth = Math.max(0, this.dragDepth - 1);
            }
        },
        handleDragOver(event) {
            if (this.isFileDrag(event)) {
                event.preventDefault();
            }
        },
        handleDrop(event) {
            if (!this.isFileDrag(event)) {
                return;
            }

            event.preventDefault();
            this.dragDepth = 0;

            const files = Array.from(event.dataTransfer.files);
            if (!files.length || this.uploading) {
                return;
            }

            if (!this.uploadUrl?.trim()) {
                this.$emit('files-dropped', files);
                return;
            }

            void this.uploadFiles(files);
        },
        async uploadFiles(files) {
            this.uploading = true;

            try {
                const { default: alertify } = await import('alertifyjs');

                for (const file of files) {
                    if (file.size > this.maxFileSize) {
                        alertify.error('Datne ir pārāk liela');
                        return;
                    }

                    this.progress = null;

                    try {
                        await this.uploadFile(file);
                    } catch (error) {
                        alertify.error('Augšupielāde neizdevās');
                        console.error(error);
                        return;
                    }

                    alertify.success('Augšupielāde ir sekmīgi pabeigta');
                }

                this.$emit('uploadSuccess');
            } finally {
                this.uploading = false;
                this.progress = null;
                this.dragDepth = 0;
            }
        },
        uploadFile(file) {
            const formData = new FormData();
            formData.append('filename', file.name);
            formData.append('file', file);

            if (this.uploadToStatus5) {
                formData.append('status', 5);
            }
            if (this.attachableType) {
                formData.append('attachable_type', this.attachableType);
            }
            if (this.attachableId) {
                formData.append('attachable_id', this.attachableId);
            }

            return axios.post(this.uploadUrl, formData, {
                onUploadProgress: ({ loaded, total }) => {
                    this.progress = total ? Math.round((loaded / total) * 100) : null;
                },
            });
        },
    },
};
</script>

<style scoped>
.dropzone-overlay {
    position: fixed;
    inset: 0;
    z-index: 999999;
    display: grid;
    place-items: center;
    padding: 1rem;
    pointer-events: none;
    background: rgb(0 0 0 / 55%);
    color: #fff;
    text-align: center;
    text-shadow: 1px 1px 2px #000;
    font: 700 clamp(1.5rem, 5vw, 2.625rem) Oswald, "DejaVu Sans", Tahoma, sans-serif;
}

.dropzone-overlay--contained {
    position: absolute;
    z-index: 1000;
    overflow: hidden;
    border-radius: inherit;
    font-size: 1.375rem;
}

.dropzone-content {
    display: grid;
    justify-items: center;
    gap: .5rem;
    width: min(100%, 20rem);
}

.dropzone-content progress {
    width: 100%;
    height: .875rem;
    accent-color: var(--primary-base);
}
</style>
