<template>
    <div class="d-flex flex-wrap align-items-center gap-2">
        <button
            v-for="tag in modelValue"
            :key="tag"
            type="button"
            class="badge badge-info rounded-pill border-0"
            :aria-label="`Remove ${tag}`"
            @click="removeTag(tag)"
        >
            {{ tag }} <span aria-hidden="true">×</span>
        </button>
        <input
            ref="input"
            v-model="draft"
            type="text"
            class="form-control tag-input-field"
            :aria-label="label"
            :placeholder="placeholder"
            @keydown="handleKey"
        />
    </div>
</template>

<script>
export default {
    name: 'TagInput',
    props: {
        modelValue: { type: Array, default: () => [] },
        label: { type: String, default: 'Tags. Press Enter or comma to add a tag.' },
        placeholder: { type: String, default: 'Add a tag' },
    },
    emits: ['update:modelValue'],
    data() {
        return { draft: '' };
    },
    methods: {
        handleKey(event) {
            if (event.isComposing || !['Enter', ','].includes(event.key)) {
                return;
            }

            event.preventDefault();
            const tag = this.draft.trim();
            if (tag && !this.modelValue.includes(tag)) {
                this.$emit('update:modelValue', [...this.modelValue, tag]);
            }
            this.draft = '';
        },
        removeTag(tag) {
            this.$emit('update:modelValue', this.modelValue.filter((value) => value !== tag));
            this.$refs.input.focus();
        },
    },
};
</script>

<style scoped>
.tag-input-field {
    flex: 1 1 8rem;
    min-inline-size: 0;
}
</style>
